<script setup lang="ts">
import {computed,ref,reactive,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {Button,Input,useHostContext} from '@openclaw-plugins/control-ui-kit';
import type {MaintenanceOperation,maintenanceCatalog} from '../../agent-repo-api/maintenance.mjs';
import {useManagementRequest} from './management-request';
import MaintenanceDetail from './MaintenanceDetail.vue';
import {type Skill,type SkillSource,type Provider,type Policy,type Confirmation,type Retry,type Action,time,summary,sourceName,skillState,providerStatus} from './maintenance-model';
const props=withDefaults(defineProps<{agentId:string;sources?:SkillSource[];scopeKey?:string}>(),{sources:()=>[],scopeKey:''});
const emit=defineEmits<{view:[value:string];query:[value:string]}>();
const context=useHostContext(),request=useManagementRequest(context,()=>props.agentId),root=ref<HTMLElement>(),search=ref<InstanceType<typeof Input>>();
const data=ref<Awaited<ReturnType<typeof maintenanceCatalog>>>(),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),confirmation=ref<Confirmation|null>(null),retry=ref<Retry|null>(null),query=ref(''),view=ref('skills'),selected=ref<{kind:'skill'|'cli';key:string}|null>(null),tab=ref('overview');
const drafts=reactive(new Map<string,{revision?:string;settings:Policy}>());
const writable=computed(()=>context.value.host.connection.canWrite===true),safe=(value:unknown)=>context.value.host.redact(String(value??''));
const providers=computed<Provider[]>(()=>data.value?.providers??[]),cliProviders=computed(()=>providers.value.filter(p=>p.kind!=='generated-skill'&&p.id!=='agent-repo.main-skill'));
const skills=computed<Skill[]>(()=>[
 ...providers.value.flatMap(provider=>(provider.skills?.length?provider.skills:provider.kind==='generated-skill'||provider.id==='agent-repo.main-skill'?[{name:provider.id}]:[]).map(skill=>({...skill,key:provider.id+':'+skill.name,label:provider.kind==='generated-skill'||provider.id==='agent-repo.main-skill'?provider.label:skill.name,sourceLabel:provider.ownerLabel??provider.label,scope:provider.kind==='generated-skill'||provider.id==='agent-repo.main-skill'?provider.scope:skill.scope??'以技能说明与当前任务权限为准',state:provider.state,provider,cli:cliProviders.value.includes(provider)?provider:null}))),
 ...props.sources.flatMap(source=>(source.skills??[]).map(skill=>({...skill,key:'repo:'+skill.path,label:skill.name,sourceLabel:sourceName(source.source),scope:source.directory??'',state:skill.status??(skill.disabledReason?'disabled':source.state==='dirty'?'pending_commit':'candidate'),warning:source.warning,cli:null}))),
]);
const selectedSkill=computed(()=>selected.value?.kind==='skill'?skills.value.find(row=>row.key===selected.value?.key):undefined);
const provider=computed(()=>selected.value?.kind==='cli'?cliProviders.value.find(row=>row.id===selected.value?.key):selectedSkill.value?.provider);
const policy=computed<Policy>(()=>provider.value?drafts.get(provider.value.id)?.settings??{autoUpdate:provider.value.policy?.autoUpdate??false,version:provider.value.policy?.version??'',updateCheckIntervalHours:provider.value.policy?.updateCheckIntervalHours??24}:{autoUpdate:false,version:'',updateCheckIntervalHours:24});
watch(provider,p=>{if(p&&drafts.get(p.id)?.revision!==p.revision)drafts.delete(p.id);});
function savePolicy(settings:Policy){if(provider.value)drafts.set(provider.value.id,{revision:provider.value.revision,settings});}
function matches(values:unknown[]){const terms=query.value.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean),text=values.join(' ').toLocaleLowerCase();return terms.every(t=>text.includes(t));}
const matchingSkills=computed(()=>skills.value.filter(row=>matches([row.label,row.name,row.path,row.description,row.sourceLabel,row.cli?.label])));
const matchingProviders=computed(()=>cliProviders.value.filter(row=>matches([row.label,...(row.skills??[]).map(s=>s.name)])));
const matchingCount=computed(()=>view.value==='skills'?matchingSkills.value.length:matchingProviders.value.length),itemCount=computed(()=>view.value==='skills'?skills.value.length:cliProviders.value.length);
let epoch=0,timer:ReturnType<typeof setInterval>,alive=true;
async function refresh(){if(busy.value||!context.value.presented||!context.value.host.connection.canRead)return;const token=++epoch,valid=request.capture();loading.value=true;error.value='';try{const next=await request.invoke<Awaited<ReturnType<typeof maintenanceCatalog>>>('maintenance',{});if(next?.apiVersion!==1)throw Error('维护接口版本不兼容，请升级配套插件');if(valid()&&token===epoch)data.value=next;}catch(e){if(valid()&&token===epoch)error.value=safe(e instanceof Error?e.message:e);}finally{if(valid()&&token===epoch)loading.value=false;}}
async function execute(action?:Action){const p=provider.value;if(busy.value||!writable.value||(!retry.value&&(!p||!action)))return;const token=epoch,valid=request.capture();busy.value=true;error.value='';notice.value='';const input=retry.value??{providerId:p!.id,action:action!.id,expectedRevision:confirmation.value?.providerId===p!.id?confirmation.value.revision:p!.revision!,requestId:crypto.randomUUID(),confirmed:true as const,...(confirmation.value?.settings?{settings:confirmation.value.settings}:{})};retry.value=input;
 try{const operation=await request.invoke<MaintenanceOperation>('maintenanceRun',input as unknown as Record<string,unknown>);if(!valid()||token!==epoch)return;retry.value=null;confirmation.value=null;drafts.delete(input.providerId);notice.value=operation.status==='succeeded'?'维护操作已完成。':operation.status==='failed'?'维护操作失败，请在维护记录中核对原因。':operation.status==='unknown'?'维护结果待核验，请查看维护记录，避免重复执行。':'维护请求已受理，可在维护记录中查看结果。';tab.value='history';}catch(e){if(valid()&&token===epoch)error.value=safe(e instanceof Error?e.message:e)+'；结果未确认，请重试原维护请求以核查，避免重复执行。';}finally{if(valid()&&token===epoch){busy.value=false;if(!retry.value)await refresh();}}}
function confirm(action:Action,settings?:Policy){const p=provider.value;if(!p?.revision||!writable.value||busy.value||retry.value)return;confirmation.value={providerId:p.id,action,revision:p.revision,...(settings?{settings}:{})};}
function setView(value:string){view.value=value;emit('view',value);}
function changeView(value:string){setView(value);selected.value=null;confirmation.value=null;query.value='';}
function choose(kind:'skill'|'cli',key:string){selected.value={kind,key};tab.value='overview';confirmation.value=null;setView(kind==='skill'?'skills':'cli');}
async function back(){const key=selected.value?.key;selected.value=null;confirmation.value=null;await nextTick();Array.from(root.value?.querySelectorAll<HTMLElement>('[data-item-key]')??[]).find(n=>n.dataset.itemKey===key)?.focus({preventScroll:true});}
function exportDiagnostics(){const document=root.value!.ownerDocument,url=URL.createObjectURL(new Blob([safe(JSON.stringify({...data.value,providers:providers.value.map(({body,...p})=>p)},null,2))],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='skill-maintenance-diagnostics.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),0);}
watch(query,value=>emit('query',value));
watch(()=>props.scopeKey,()=>{epoch++;request.invalidate();if(selected.value?.key.startsWith('repo:'))selected.value=null;query.value='';confirmation.value=null;retry.value=null;busy.value=false;void refresh();});
watch([()=>props.agentId,()=>context.value.presented,()=>context.value.host.connection.canRead,()=>context.value.host.connection.canWrite],()=>{epoch++;request.invalidate();data.value=undefined;confirmation.value=null;retry.value=null;drafts.clear();selected.value=null;busy.value=false;loading.value=false;error.value='';notice.value='';void refresh();},{flush:'sync'});
onMounted(()=>{void refresh();timer=setInterval(()=>{if(alive&&context.value.presented&&!confirmation.value&&!retry.value&&tab.value!=='settings'&&data.value?.providers.some(p=>p.history?.some(o=>o.status==='running')))void refresh();},3000);});onBeforeUnmount(()=>{alive=false;epoch++;clearInterval(timer);});
defineExpose({refresh,view});
</script>
<template><section ref="root" class="ar-maintenance" aria-label="技能与关联 CLI" :aria-busy="loading||busy"><header class="ar-maintenance-heading"><h2>技能与关联 CLI</h2><Button variant="outline" :disabled="loading||busy" @click="refresh">{{loading?'正在刷新…':'刷新状态'}}</Button></header><nav class="ar-maintenance-views" aria-label="技能管理视图"><Button v-for="[key,label] in [['skills','技能'],['cli','关联 CLI']]" :key="key" variant="ghost" :aria-current="view===key?'page':undefined" @click="changeView(key!)">{{label}}</Button></nav><p v-if="error" role="alert" class="ar-error">{{error}}</p><p v-if="notice" role="status" class="ar-maintenance-notice">{{notice}}</p><p v-if="!writable" class="ar-muted">只读模式：可以查看详情，维护操作需要写入权限。</p><Button v-if="retry" :disabled="busy||!writable" @click="execute()">重试原维护请求</Button><div class="ar-maintenance-layout" :class="{'ar-has-detail':!!selectedSkill||!!provider}"><section class="ar-maintenance-list" :aria-label="view==='skills'?'技能列表':'关联 CLI 列表'"><Input ref="search" v-model="query" type="search" aria-label="搜索技能或关联 CLI" :placeholder="view==='skills'?'搜索技能名称、用途或 CLI':'搜索 CLI 或关联技能'"/><p class="ar-maintenance-count" role="status">{{query?matchingCount+' / '+itemCount+' 项匹配':itemCount+(view==='skills'?' 个技能':' 个关联 CLI')}}</p><table class="ar-maintenance-table" :class="{'ar-cli-table':view==='cli'}"><thead><tr><th scope="col">{{view==='skills'?'技能与用途':'CLI 与来源'}}</th><th scope="col">{{view==='skills'?'状态':'版本与更新'}}</th></tr></thead><tbody><template v-if="view==='skills'"><tr v-for="row in matchingSkills" :key="row.key" :class="{'ar-selected':selected?.key===row.key}" @click="choose('skill',row.key)"><td class="ar-maintenance-identity"><Button class="ar-maintenance-item ocp:h-auto ocp:whitespace-normal" variant="ghost" :data-item-key="row.key" :aria-pressed="selected?.key===row.key" @click.stop="choose('skill',row.key)">{{safe(row.label)}}</Button><span class="ar-maintenance-summary">{{safe(summary(row.description)||'查看技能说明')}}</span><small>{{safe([row.sourceLabel,row.cli?.label].filter(Boolean).join(' · '))}}</small></td><td class="ar-maintenance-state"><span class="ar-maintenance-badge">{{skillState(row)}}</span></td></tr></template><template v-else><tr v-for="row in matchingProviders" :key="row.id" :class="{'ar-selected':selected?.key===row.id}" @click="choose('cli',row.id)"><td class="ar-maintenance-identity"><Button class="ar-maintenance-item ocp:h-auto ocp:whitespace-normal" variant="ghost" :data-item-key="row.id" :aria-pressed="selected?.key===row.id" @click.stop="choose('cli',row.id)">{{safe(row.label)}}</Button><span class="ar-maintenance-summary">{{safe(row.ownerLabel??row.label)}}</span><small>{{row.skills?.length??0}} 个关联技能</small></td><td class="ar-maintenance-state"><span class="ar-maintenance-badge">{{providerStatus(row)}}</span><small>{{safe(row.versions?.current??'版本未知')}}</small><small>{{row.policy?row.policy.autoUpdate?'自动更新已开启':'自动更新已关闭':'未提供更新设置'}}</small></td></tr></template></tbody></table><p v-if="!matchingCount" class="ar-maintenance-empty">{{query?'没有匹配的结果。':loading?'正在读取…':view==='skills'&&sources.length&&sources.every(s=>s.state==='unavailable')?'此范围暂不可扫描':view==='cli'?'尚无提供方声明关联 CLI；仓库技能仍可查看。':'当前范围没有可显示的技能。'}}</p><template v-for="(source,index) in sources" :key="index"><p v-if="source.warning" class="ar-warning">{{safe(source.warning)}}</p></template><p v-if="data" class="ar-meta">维护状态检查于 {{time(data.observedAt)}}</p></section><MaintenanceDetail v-if="selectedSkill||provider" :skill="selectedSkill" :provider="provider" :rows="skills" :tab="tab" :safe="safe" :writable="writable" :busy="busy" :loading="loading" :retry="!!retry" :confirmation="confirmation" :policy="policy" @choose="choose" @back="back" @tab="tab=$event;confirmation=null" @confirm="confirm" @execute="execute" @cancel="confirmation=null" @export="exportDiagnostics" @policy="savePolicy"/><aside v-else class="ar-maintenance-empty">选择一项查看详情</aside></div></section></template>
